async function fetchDocumentText(address, ctx = {}) {
  try {
    return await fetch("/leapi", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        token: TOKEN,
        operation: "documentText",
        address,
        source: ctx.source || "",
        base: ctx.base || ""
      })
    }).then((r) => r.json());
  } catch {
    return { error: t("Could not reach the server.") };
  }
}

